import React, { useEffect, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { EmailAuthProvider, onAuthStateChanged, reauthenticateWithCredential, sendPasswordResetEmail, signInWithEmailAndPassword, signOut, updatePassword, type User } from 'firebase/auth';
import { doc, getDoc, updateDoc } from 'firebase/firestore';
import { createNote, createPin, deleteLocalNote, deleteLocalPin, listNotes, listPins, putNote, putPin, queuePinOperation, type Note, type Pin } from './db';
import { firebaseConfigError, getSurfaceFirebase } from './firebase';
import { readSurfaceEntitlement, type SurfaceEntitlement } from './entitlement';
import { flushPinSync as flushPinSyncNow, hydratePins } from './sync';
import { normalizeIndianMobile, paymentAmount, type PaymentTier } from './payments';
import { deleteMedia, listMedia, objectUrl, putMedia, saveMedia, type SurfaceMedia } from './media';
import { formatSurfaceLocation, readSurfaceLocation, type SurfaceLocation } from './location';
import { flushCloudSync, hydrateMediaMetadata, hydrateNotes, queueNote, queueNoteDelete, uploadMedia } from './cloudSync';
import { NativeCamera, NativeCaptures, NativeHome, NativeMediaGrid, NativeNotes, NativePins, NativeProfile, NativeViewer } from './nativeScreens';
import { SurfaceDialog } from './SurfaceDialog';
import { InformationPage } from './InformationPages';
import './styles.css';

type Route = 'home' | 'gallery' | 'notes' | 'camera' | 'captures' | 'pins' | 'profile' | 'account' | 'surface-pro' | 'new-pin' | 'pin-detail' | 'edit-pin' | 'new-note' | 'note-detail' | 'edit-note' | 'search' | 'privacy' | 'terms' | 'refunds' | 'help' | 'payment-return';
const flushPinSync = async (entitlement: SurfaceEntitlement | null): Promise<void> => { if (entitlement) await flushPinSyncNow(entitlement); };
const routeFromHash = (): { route: Route; id?: string } => { const hashValue = window.location.hash.replace(/^#\/?/, ''); const pathValue = window.location.pathname.replace(/^\/+|\/+$/g, ''); const value = hashValue || pathValue; if (value.startsWith('pins/new')) return { route: 'new-pin', id: value.split('/')[2] }; if (value.startsWith('pins/edit/')) return { route: 'edit-pin', id: value.slice(10) }; if (value.startsWith('pins/')) return { route: 'pin-detail', id: value.slice(5) }; if (value === 'notes/new') return { route: 'new-note' }; if (value.startsWith('notes/edit/')) return { route: 'edit-note', id: value.slice(11) }; if (value.startsWith('notes/')) return { route: 'note-detail', id: value.slice(6) }; const [base, id] = value.split('/'); return { route: (['home', 'gallery', 'notes', 'camera', 'captures', 'pins', 'profile', 'account', 'search', 'surface-pro', 'privacy', 'terms', 'refunds', 'help', 'payment-return'].includes(base) ? base : 'home') as Route, id };
};

function App() {
  const [user, setUser] = useState<User | null>(null); const [navigation, setNavigation] = useState(routeFromHash); const [pins, setPins] = useState<Pin[]>([]); const [notes, setNotes] = useState<Note[]>([]); const [media, setMedia] = useState<SurfaceMedia[]>([]);
  const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [message, setMessage] = useState(''); const [authMode, setAuthMode] = useState<'sign-in' | 'recovery'>('sign-in'); const [resetLoading, setResetLoading] = useState(false); const [entitlement, setEntitlement] = useState<SurfaceEntitlement | null>(null); const configError = firebaseConfigError();
  const go = (route: Route, id?: string) => { const hash = route === 'new-pin' ? `#pins/new${id ? `/${id}` : ''}` : route === 'new-note' ? '#notes/new' : route === 'edit-note' && id ? `#notes/edit/${id}` : route === 'edit-pin' && id ? `#pins/edit/${id}` : route === 'pin-detail' && id ? `#pins/${id}` : route === 'note-detail' && id ? `#notes/${id}` : route === 'camera' && id ? `#camera/${id}` : `#${route}`; window.location.hash = hash; setNavigation({ route, id }); };
  useEffect(() => { const changed = () => setNavigation(routeFromHash()); window.addEventListener('hashchange', changed); return () => window.removeEventListener('hashchange', changed); }, []);
  useEffect(() => { void listMedia().then(setMedia); }, []);
  useEffect(() => { if (configError) return; const { auth, firestore } = getSurfaceFirebase(); return onAuthStateChanged(auth, (nextUser) => { setUser(nextUser); if (!nextUser) { setEntitlement(null); void Promise.all([listPins(), listNotes()]).then(([nextPins, nextNotes]) => { setPins(nextPins); setNotes(nextNotes); }); return; } void Promise.all([readSurfaceEntitlement(firestore, nextUser.uid), listNotes()]).then(async ([nextEntitlement]) => { setEntitlement(nextEntitlement); setNotes(await hydrateNotes(nextEntitlement)); setPins(await hydratePins(nextEntitlement)); await hydrateMediaMetadata(nextEntitlement); setMedia(await listMedia()); await flushPinSync(nextEntitlement); setMessage(await flushCloudSync(nextEntitlement)); }).catch(() => setMessage('Account state is temporarily unavailable. Local data remains safe.')); }); }, [configError]);
  const refreshEntitlement = async () => { if (!user) return; setEntitlement(await readSurfaceEntitlement(getSurfaceFirebase().firestore, user.uid)); };
  async function signIn() { try { await signInWithEmailAndPassword(getSurfaceFirebase().auth, email.trim(), password); setMessage(''); } catch { setMessage('Sign in failed. Check your email and password.'); } }
  async function sendResetEmail() { if (resetLoading) return; setResetLoading(true); setMessage(''); try { await sendPasswordResetEmail(getSurfaceFirebase().auth, email.trim()); setMessage('Password reset email sent. Check your inbox and spam folder.'); } catch (error) { const code = (error as { code?: string }).code; setMessage(code === 'auth/invalid-email' ? 'Enter a valid email address.' : 'Password reset could not be sent. Check your connection and try again.'); } finally { setResetLoading(false); } }
  if (configError) return <main className="phone-shell"><p className="eyebrow">Surface</p><h1>Configuration needed</h1><p>{configError}</p></main>;
  if ((['privacy', 'terms', 'refunds', 'help'] as Route[]).includes(navigation.route)) return <main className="phone-shell app-shell"><InformationPage kind={navigation.route as 'privacy' | 'terms' | 'refunds' | 'help'} onBack={() => go(user ? 'profile' : 'home')} /></main>;
  if (!user) return <main className="phone-shell auth"><img src="/surface-logo.svg" alt="Surface" className="logo" /><h1>Surface</h1><p className="tagline">Go Beyond</p>{authMode === 'sign-in' ? <><form onSubmit={(event) => { event.preventDefault(); void signIn(); }}><input aria-label="Email" type="email" placeholder="Email" value={email} onChange={(event) => setEmail(event.target.value)} required /><input aria-label="Password" type="password" placeholder="Password" value={password} onChange={(event) => setPassword(event.target.value)} required /><button type="submit">Sign in</button></form><button type="button" className="text-button auth-recovery-link" onClick={() => { setAuthMode('recovery'); setMessage(''); }}>Forgot password?</button></> : <form onSubmit={(event) => { event.preventDefault(); void sendResetEmail(); }}><input aria-label="Reset email" type="email" placeholder="Email" value={email} onChange={(event) => setEmail(event.target.value)} required /><button type="submit" disabled={resetLoading}>{resetLoading ? 'Sending…' : 'Send reset email'}</button><button type="button" className="text-button" onClick={() => { setAuthMode('sign-in'); setMessage(''); }}>Back to sign in</button></form>}{message && <p className="message" role="status">{message}</p>}</main>;
  const selectedPin = navigation.id ? pins.find((item) => item.id === navigation.id) : undefined; const selectedNote = navigation.id ? notes.find((item) => item.id === navigation.id) : undefined; const noteCameraId = navigation.route === 'camera' && navigation.id?.startsWith('note:') ? navigation.id.slice(5) : undefined; const pinCameraId = navigation.route === 'camera' && navigation.id?.startsWith('pin:') ? navigation.id.slice(4) : undefined; const noteForPin = navigation.route === 'new-pin' && navigation.id?.startsWith('note:') ? notes.find((item) => item.id === navigation.id!.slice(5)) : undefined; const captureForPin = navigation.route === 'new-pin' && navigation.id && !noteForPin ? media.find((item) => item.id === navigation.id) : undefined; const existingNotePin = noteForPin ? pins.find((item) => item.sourceNoteId === noteForPin.id) : undefined;
  return <main className={`phone-shell app-shell ${navigation.route === 'home' ? 'home-shell' : ''} ${navigation.route === 'gallery' ? 'gallery-shell' : ''} ${navigation.route === 'camera' ? 'camera-shell' : ''} ${navigation.route === 'surface-pro' ? 'subscription-shell' : ''} ${navigation.route === 'captures' ? 'captures-shell' : ''} ${navigation.route === 'profile' ? 'profile-shell' : ''} ${navigation.route === 'account' ? 'account-shell' : ''} ${['notes', 'new-note', 'edit-note', 'note-detail'].includes(navigation.route) ? 'notes-shell' : ''} ${['pins', 'new-pin', 'edit-pin', 'pin-detail'].includes(navigation.route) ? 'pins-shell' : ''}`}><div className="app-content">{navigation.route === 'home' && <header className="topbar"><button className="brand-button" onClick={() => go('home')}><h1>Surface</h1></button><button className="profile-mark" aria-label="Open Profile" onClick={() => go('profile')}><img src="/surface-logo.svg" alt="" />{entitlement?.tier === 'FREE' && <span className="profile-attention">!</span>}</button></header>}
    {navigation.route === 'home' && <NativeHome routeTo={go} isPro={entitlement?.tier !== 'FREE'} />}
    {navigation.route === 'pins' && <NativePins pins={pins} media={media} onCreate={() => go('new-pin')} onOpen={(id) => go('pin-detail', id)} onDelete={(id) => { void deleteLocalPin(id); setPins((current) => current.filter((item) => item.id !== id)); if (entitlement && entitlement.tier !== 'FREE') { void queuePinOperation({ id: `delete:${id}`, kind: 'DELETE_PIN', pinId: id }).then(() => flushPinSync(entitlement)); } }} />}
    {navigation.route === 'new-pin' && <PinForm title="Create PIN" initial={noteForPin ? { name: noteForPin.name, phone: noteForPin.phone, about: noteForPin.body, locationLabel: noteForPin.locationLabel } : undefined} sourceMedia={captureForPin} dateKey={noteForPin?.dateKey} locationLabel={noteForPin?.locationLabel ?? formatSurfaceLocation(readSurfaceLocation())} existingPins={pins} pinLimitReached={entitlement?.tier === 'FREE' && pins.length >= 5} existingSourcePinId={existingNotePin?.id} onExisting={() => { if (existingNotePin) go('pin-detail', existingNotePin.id); }} onCancel={() => noteForPin ? go('edit-note', noteForPin.id) : go('pins')} onSave={async (data) => { const pin = await createPin(data.name, data.about, data.phone, data.locationLabel); const linked = captureForPin; const linkedPin = { ...pin, ...(linked ? { mediaIds: [linked.id] } : {}), ...(noteForPin ? { sourceNoteId: noteForPin.id } : {}) }; if (linked) { await putMedia({ ...linked, pinIds: [...new Set([...(linked.pinIds ?? []), linkedPin.id])] }); setMedia((items) => items.map((item) => item.id === linked.id ? { ...item, pinIds: [...new Set([...(item.pinIds ?? []), linkedPin.id])] } : item)); } await putPin(linkedPin); setPins((current) => [linkedPin, ...current]); const paid = entitlement; if (paid && paid.tier !== 'FREE') { await queuePinOperation({ id: `upsert:${linkedPin.id}`, kind: 'UPSERT_PIN', pinId: linkedPin.id, payload: linkedPin }); await flushPinSync(paid); } go('pin-detail', linkedPin.id); }} />}
    {navigation.route === 'pin-detail' && selectedPin && <PinDetail pin={selectedPin} media={media} isPro={entitlement?.tier !== 'FREE'} onBack={() => go('pins')} onEdit={() => go('edit-pin', selectedPin.id)} onCamera={() => go('camera', `pin:${selectedPin.id}`)} onDeletePin={async () => { await deleteLocalPin(selectedPin.id); setPins((current) => current.filter((item) => item.id !== selectedPin.id)); if (entitlement?.tier !== 'FREE') await queuePinOperation({ id: `delete:${selectedPin.id}`, kind: 'DELETE_PIN', pinId: selectedPin.id }); go('pins'); }} onDeleteNote={selectedPin.sourceNoteId ? async () => { await deleteLocalNote(selectedPin.sourceNoteId!); await deleteLocalPin(selectedPin.id); setNotes((current) => current.filter((item) => item.id !== selectedPin.sourceNoteId)); setPins((current) => current.filter((item) => item.id !== selectedPin.id)); if (entitlement) { await queueNoteDelete(selectedPin.sourceNoteId!, entitlement); await queuePinOperation({ id: `delete:${selectedPin.id}`, kind: 'DELETE_PIN', pinId: selectedPin.id }); void flushCloudSync(entitlement); } go('pins'); } : undefined} onFollowUp={async (at, reason) => { const updated = { ...selectedPin, followUpAt: at, followUpReason: reason, updatedAt: Date.now() }; await putPin(updated); setPins((current) => current.map((item) => item.id === updated.id ? updated : item)); setMessage('Follow-up saved.'); }} />}
    {navigation.route === 'edit-pin' && selectedPin && <PinForm title="Edit PIN" initial={selectedPin} onCancel={() => go('pin-detail', selectedPin.id)} onSave={async (data) => { const updated = { ...selectedPin, ...data, updatedAt: Date.now() }; await putPin(updated); setPins((current) => current.map((item) => item.id === updated.id ? updated : item)); if (entitlement?.tier !== 'FREE') await queuePinOperation({ id: `upsert:${updated.id}`, kind: 'UPSERT_PIN', pinId: updated.id, payload: updated }); go('pin-detail', updated.id); }} />}
    {navigation.route === 'notes' && <NativeNotes notes={notes} onCreate={() => go('new-note')} onOpen={(id) => go('edit-note', id)} onDelete={(id) => { void deleteLocalNote(id); setNotes((current) => current.filter((item) => item.id !== id)); if (entitlement) { void queueNoteDelete(id, entitlement).then(() => flushCloudSync(entitlement)); } }} />}
    {navigation.route === 'new-note' && <NoteForm title="New block" locationLabel={formatSurfaceLocation(readSurfaceLocation())} onCancel={() => go('notes')} onSave={async (data) => { const note = await createNote(data.name, data.phone, data.body, data.locationLabel); setNotes((current) => [note, ...current]); if (entitlement) { await queueNote(note, entitlement); void flushCloudSync(entitlement); } go('note-detail', note.id); }} onCamera={async (data) => { const note = await createNote(data.name, data.phone, data.body, data.locationLabel); setNotes((current) => [note, ...current]); if (entitlement) { await queueNote(note, entitlement); void flushCloudSync(entitlement); } go('camera', `note:${note.id}`); }} />}
    {navigation.route === 'note-detail' && selectedNote && <NoteDetail note={selectedNote} onBack={() => go('notes')} onEdit={() => go('edit-note', selectedNote.id)} onDelete={async () => { await deleteLocalNote(selectedNote.id); setNotes((current) => current.filter((item) => item.id !== selectedNote.id)); if (entitlement) { await queueNoteDelete(selectedNote.id, entitlement); void flushCloudSync(entitlement); } go('notes'); }} />}
    {navigation.route === 'edit-note' && selectedNote && <NoteForm title="Edit block" initial={selectedNote} image={selectedNote.imageMediaId ? media.find((item) => item.id === selectedNote.imageMediaId) : undefined} locationLabel={selectedNote.locationLabel ?? ''} onCancel={() => go('note-detail', selectedNote.id)} onSave={async (data) => { const updated = { ...selectedNote, ...data, updatedAt: Date.now() }; await putNote(updated); setNotes((current) => current.map((item) => item.id === updated.id ? updated : item)); if (entitlement) { await queueNote(updated, entitlement); void flushCloudSync(entitlement); } go('note-detail', updated.id); }} onCamera={async (data) => { const updated = { ...selectedNote, ...data, updatedAt: Date.now() }; await putNote(updated); setNotes((current) => current.map((item) => item.id === updated.id ? updated : item)); if (entitlement) { await queueNote(updated, entitlement); void flushCloudSync(entitlement); } go('camera', `note:${updated.id}`); }} onCreatePin={() => go('new-pin', `note:${selectedNote.id}`)} />}
    {navigation.route === 'search' && <Search pins={pins} notes={notes} onPin={(id) => go('pin-detail', id)} onNote={(id) => go('note-detail', id)} isPro={entitlement?.tier !== 'FREE'} />}
    {navigation.route === 'surface-pro' && <SurfacePro user={user} entitlement={entitlement} onAccount={() => go('account')} onClose={() => go('profile')} onRefresh={refreshEntitlement} />}
    {navigation.route === 'payment-return' && <PaymentReturn onBack={() => go('surface-pro')} onRefresh={refreshEntitlement} />}
    {(['privacy', 'terms', 'refunds', 'help'] as Route[]).includes(navigation.route) && <InformationPage kind={navigation.route as 'privacy' | 'terms' | 'refunds' | 'help'} onBack={() => go('profile')} />}
    {navigation.route === 'camera' && <NativeCamera onBack={() => noteCameraId ? go('edit-note', noteCameraId) : pinCameraId ? go('pin-detail', pinCameraId) : go('home')} location={readSurfaceLocation()} pins={pins} save={(file, location) => saveMedia(file, location, true)} onSaved={(item) => { setMedia((items) => [item, ...items]); if (entitlement) void uploadMedia(item, entitlement).catch(() => setMessage('Media sync pending.')); const note = noteCameraId ? notes.find((entry) => entry.id === noteCameraId) : undefined; if (note) { const updated = { ...note, imageMediaId: item.id, updatedAt: Date.now() }; void putNote(updated); setNotes((items) => items.map((entry) => entry.id === updated.id ? updated : entry)); if (entitlement) { void queueNote(updated, entitlement).then(() => flushCloudSync(entitlement)); } go('edit-note', updated.id); return; } const pin = pinCameraId ? pins.find((entry) => entry.id === pinCameraId) : undefined; if (pin) { const updated = { ...pin, mediaIds: [...new Set([...(pin.mediaIds ?? []), item.id])], updatedAt: Date.now() }; void putPin(updated); void putMedia({ ...item, pinIds: [...new Set([...(item.pinIds ?? []), updated.id])] }); setPins((items) => items.map((entry) => entry.id === updated.id ? updated : entry)); setMedia((items) => items.map((entry) => entry.id === item.id ? { ...item, pinIds: [...new Set([...(item.pinIds ?? []), updated.id])] } : entry)); if (entitlement?.tier !== 'FREE') { void queuePinOperation({ id: `upsert:${updated.id}`, kind: 'UPSERT_PIN', pinId: updated.id, payload: updated }).then(() => flushPinSync(entitlement)); } go('pin-detail', updated.id); return; } go('captures'); }} onCreatePin={(item) => { setMedia((items) => [item, ...items]); if (entitlement) void uploadMedia(item, entitlement).catch(() => setMessage('Media sync pending.')); go('new-pin', item.id); }} onConnectExisting={async (item, pinId) => { const pin = pins.find((entry) => entry.id === pinId); if (!pin) return; const updated = { ...pin, mediaIds: [...new Set([...(pin.mediaIds ?? []), item.id])], updatedAt: Date.now() }; await putPin(updated); await putMedia({ ...item, pinIds: [pinId] }); setPins((current) => current.map((entry) => entry.id === pinId ? updated : entry)); setMedia((current) => [item, ...current]); if (entitlement) void uploadMedia(item, entitlement).catch(() => setMessage('Media sync pending.')); setMessage('Capture connected to PIN.'); go('captures'); }} onMessage={setMessage} />}
    {navigation.route === 'gallery' && <NativeMediaGrid title="Surface Gallery" items={media.filter((item) => !item.capture)} pins={pins} onImport={async (file) => { const item = await saveMedia(file, null, false); setMedia((items) => [item, ...items]); if (entitlement) void uploadMedia(item, entitlement).catch(() => setMessage('Media sync pending.')); }} onDelete={async (id) => { const item = media.find((entry) => entry.id === id); if (item?.pinIds?.length) { setMessage('Remove this image from its PIN before deleting it.'); return; } await deleteMedia(id); setMedia((items) => items.filter((entry) => entry.id !== id)); }} />}
    {navigation.route === 'captures' && <NativeCaptures items={media.filter((item) => item.capture)} pins={pins} onCamera={() => go('camera')} onCreatePin={(id) => go('new-pin', id)} onConnectExisting={async (mediaId, pinId) => { const pin = pins.find((entry) => entry.id === pinId); const item = media.find((entry) => entry.id === mediaId); if (!pin || !item) return; const updated = { ...pin, mediaIds: [...new Set([...(pin.mediaIds ?? []), mediaId])], updatedAt: Date.now() }; await putPin(updated); await putMedia({ ...item, pinIds: [...new Set([...(item.pinIds ?? []), pinId])] }); setPins((current) => current.map((entry) => entry.id === pinId ? updated : entry)); setMedia((current) => current.map((entry) => entry.id === mediaId ? { ...entry, pinIds: [...new Set([...(entry.pinIds ?? []), pinId])] } : entry)); setMessage('Capture connected to PIN.'); }} onDelete={async (id) => { const item = media.find((entry) => entry.id === id); if (item?.pinIds?.length) { setMessage('Remove this image from its PIN before deleting it.'); return; } await deleteMedia(id); setMedia((items) => items.filter((entry) => entry.id !== id)); }} />}
    {navigation.route === 'profile' && <NativeProfile uid={user.uid} name={user.displayName || ''} email={user.email || ''} tier={entitlement?.tier || 'FREE'} onAccount={() => go('account')} onPro={() => go('surface-pro')} onHome={() => go('home')} onEdit={() => go('account')} onInfo={(kind) => go(kind)} />}
    {navigation.route === 'account' && <Account user={user} onBack={() => go('profile')} onSignedOut={() => void signOut(getSurfaceFirebase().auth)} setMessage={setMessage} />}
    {message && <p className="message inline-message">{message}</p>}</div>{navigation.route === 'home' && <GroundNav route={navigation.route} routeTo={go} isPro={entitlement?.tier !== 'FREE'} />}</main>;
}

function Home({ routeTo, isPro }: { routeTo: (route: Route) => void; isPro: boolean }) { return <><div className="home-spacer" /><section className="destination-grid"><Destination title="Gallery" icon="gallery" onClick={() => routeTo('gallery')} isPro={isPro} /><Destination title="Notes" icon="notes" onClick={() => routeTo('notes')} isPro={isPro} /><Destination title="Camera" icon="camera" onClick={() => routeTo('camera')} isPro={isPro} /><Destination title="PINs" icon="pins" onClick={() => routeTo('pins')} isPro={isPro} /></section><button className={isPro ? 'primary-action' : 'surface-action'} onClick={() => routeTo('new-note')}><span>＋</span> Create Note</button></>; }
function Destination({ title, icon, onClick, isPro }: { title: string; icon: string; onClick: () => void; isPro: boolean }) { return <button className="destination" onClick={onClick}><img className={isPro ? 'destination-icon accent-icon' : 'destination-icon'} src={`/icons/${icon}.svg`} alt="" /><span>{title}</span></button>; }
function Pins({ pins, onCreate, onOpen }: { pins: Pin[]; onCreate: () => void; onOpen: (id: string) => void }) { return <section className="pins-view"><div className="section-heading"><h2>Surface PINs</h2><button className="icon-button" onClick={onCreate} aria-label="Create a PIN">＋</button></div>{pins.length === 0 ? <div className="empty-state"><img src="/surface-logo.svg" alt="" /><strong>Oops!!<br />Surface PINs is empty!</strong><p>People you save will appear here.</p><button className="surface-action" onClick={onCreate}>＋ Create PIN</button></div> : pins.map((pin) => <button className="pin-row" key={pin.id} onClick={() => onOpen(pin.id)}><strong>{pin.name || 'Unnamed PIN'}</strong><span>{pin.phone || 'No phone number'}</span>{pin.locationLabel && <small>{pin.locationLabel}</small>}</button>)}</section>; }
function Notes({ notes, onCreate, onOpen }: { notes: Note[]; onCreate: () => void; onOpen: (id: string) => void }) { return <section className="pins-view"><div className="section-heading"><h2>Surface Notes</h2><button className="icon-button" onClick={onCreate} aria-label="Create a note">＋</button></div>{notes.length === 0 ? <div className="empty-state"><img src="/surface-logo.svg" alt="" /><strong>Oops!!<br />Surface Notes is empty!</strong><button className="surface-action" onClick={onCreate}>＋ Create Note</button></div> : notes.map((note) => <button className="pin-row" key={note.id} onClick={() => onOpen(note.id)}><strong>{note.name || 'Note'}</strong><span>{note.phone || note.body || 'No details yet.'}</span><small>{note.dateKey}</small></button>)}</section>; }
type FormData = { name: string; phone: string; about: string; body?: string; locationLabel: string };
function PinForm({ title, initial, sourceMedia, dateKey, locationLabel, existingPins = [], pinLimitReached = false, existingSourcePinId, onExisting, onCancel, onSave }: { title: string; initial?: Pick<Pin, 'name' | 'phone' | 'about' | 'locationLabel'>; sourceMedia?: SurfaceMedia; dateKey?: string; locationLabel?: string; existingPins?: Pin[]; pinLimitReached?: boolean; existingSourcePinId?: string; onExisting?: () => void; onCancel: () => void; onSave: (data: FormData) => Promise<void> }) { const creating = title === 'Create PIN'; const [data, setData] = useState<FormData>({ name: initial?.name ?? '', phone: initial?.phone ?? '', about: initial?.about ?? '', locationLabel: initial?.locationLabel ?? locationLabel ?? '' }); const [saving, setSaving] = useState(false); const [issue, setIssue] = useState<'duplicate' | 'limit' | null>(null); const savingRef = useRef(false); const update = (key: 'name' | 'phone' | 'about', value: string) => { setIssue(null); setData((current) => ({ ...current, [key]: value })); }; const save = () => { if (savingRef.current) return; if (creating && existingSourcePinId) { onExisting?.(); return; } if (creating && pinLimitReached) { setIssue('limit'); return; } const phone = data.phone.replace(/[^\d+]/g, ''); if (creating && phone && existingPins.some((item) => item.phone.replace(/[^\d+]/g, '') === phone)) { setIssue('duplicate'); return; } savingRef.current = true; setSaving(true); void onSave({ ...data, phone }).finally(() => { savingRef.current = false; setSaving(false); }); }; return <section className="pins-editor"><h2 role="button" tabIndex={0} aria-label="Back to PINs" onClick={onCancel} onKeyDown={(event) => { if (event.key === 'Enter' || event.key === ' ') onCancel(); }}>{title}</h2>{creating && <p className="pins-editor-meta">{dateKey ?? new Date().toLocaleDateString('en-GB')} • {data.locationLabel || 'Location unavailable'}</p>}{sourceMedia && <img className="pins-editor-source-media" src={objectUrl(sourceMedia.processed)} alt="Attached capture" />}<div className="pins-editor-fields"><label><span>Name</span><input value={data.name} onChange={(event) => update('name', event.target.value)} /></label><label><span>Phone</span><input inputMode="tel" value={data.phone} onChange={(event) => update('phone', event.target.value)} /></label><label className="pins-editor-about"><span>About</span><textarea value={data.about} onChange={(event) => update('about', event.target.value)} /></label></div>{issue === 'duplicate' && <div className="pins-editor-status"><strong>Possible match found</strong><p>Edit existing or cancel. A second PIN was not created.</p></div>}{issue === 'limit' && <div className="pins-editor-status pins-editor-limit"><strong>You've used your 5 PINs.</strong><p>Surface Pro gives you unlimited PIN creation.</p></div>}<div className="pins-editor-actions"><button className="pins-save" disabled={saving} onClick={save}>{saving ? 'Saving…' : creating ? 'Confirm PIN' : 'Save'}</button></div></section>; }
type NoteEditorData = { name: string; phone: string; body: string; locationLabel: string };
function NoteForm({ title, initial, image, locationLabel, onCancel, onSave, onCamera, onCreatePin }: { title: string; initial?: Note; image?: SurfaceMedia; locationLabel: string; onCancel: () => void; onSave: (data: NoteEditorData) => Promise<void>; onCamera: (data: NoteEditorData) => Promise<void>; onCreatePin?: () => void }) { const [data, setData] = useState<NoteEditorData>({ name: initial?.name ?? '', phone: initial?.phone ?? '', body: initial?.body ?? '', locationLabel }); const [saving, setSaving] = useState(false); const savingRef = useRef(false); const commit = (action: (next: NoteEditorData) => Promise<void>) => { if (savingRef.current) return; savingRef.current = true; setSaving(true); void action(data).finally(() => { savingRef.current = false; setSaving(false); }); }; return <section className="notes-editor"><h2 role="button" tabIndex={0} aria-label="Back to notes" onClick={onCancel} onKeyDown={(event) => { if (event.key === 'Enter' || event.key === ' ') onCancel(); }}>{title}</h2><p className="notes-editor-meta">{initial?.dateKey ?? new Date().toLocaleDateString('en-GB')} • {locationLabel || 'Location unavailable'}</p><div className="notes-editor-fields">{(['name', 'phone'] as const).map((key) => <label key={key}><span>{key === 'name' ? 'Name' : 'Phone'}</span><input value={data[key]} onChange={(event) => setData({ ...data, [key]: event.target.value })} /></label>)}<label className="notes-editor-about"><span>About</span><textarea value={data.body} onChange={(event) => setData({ ...data, body: event.target.value })} /></label>{image && <img className="notes-editor-image" src={objectUrl(image.processed)} alt="Attached note" />}</div><div className="notes-editor-actions"><button className="notes-save" disabled={saving} onClick={() => commit(onSave)}>{saving ? 'Saving…' : 'Save'}</button><button className="notes-camera" disabled={saving} onClick={() => commit(onCamera)}>Camera</button>{onCreatePin && <button className="notes-camera" disabled={saving} onClick={onCreatePin}>Create PIN</button>}</div></section>; }
function PinDetail({ pin, media, isPro, onBack, onEdit, onCamera, onDeletePin, onDeleteNote, onFollowUp }: { pin: Pin; media: SurfaceMedia[]; isPro: boolean; onBack: () => void; onEdit: () => void; onCamera: () => void; onDeletePin: () => Promise<void>; onDeleteNote?: () => Promise<void>; onFollowUp: (at: number, reason: string) => Promise<void> }) { const [confirming, setConfirming] = useState<'pin' | 'note' | null>(null); const [followUp, setFollowUp] = useState(false); const [viewerIndex, setViewerIndex] = useState<number | null>(null); const [days, setDays] = useState('1'); const [reason, setReason] = useState(''); const attached = media.filter((item) => pin.mediaIds?.includes(item.id)); const download = () => { const item = attached[0]; if (!item) return; const link = document.createElement('a'); link.href = objectUrl(item.processed); link.download = `Surface-${item.dateKey.replaceAll('/', '-')}.jpg`; link.click(); }; if (viewerIndex !== null && attached[viewerIndex]) return <NativeViewer items={attached} index={viewerIndex} onClose={() => setViewerIndex(null)} onChange={setViewerIndex} />; return <section className="pins-detail"><header className="pins-detail-header"><div><h2>{pin.name || 'PIN'}</h2><p>{pin.phone || 'No number'}</p></div><button className="pin-detail-outline" onClick={onBack}>Back</button></header><div className="pins-detail-media">{attached[0] ? <button aria-label="Open attached media" onClick={() => setViewerIndex(0)}><img src={objectUrl(attached[0].processed)} alt="" /></button> : <span>PIN</span>}</div>{attached.length > 1 && <div className="pins-detail-thumbnails">{attached.map((item, index) => <button key={item.id} onClick={() => setViewerIndex(index)}><img src={objectUrl(item.processed)} alt="" /></button>)}</div>}{pin.about && <p className="pins-detail-caption">{pin.about}</p>}<div className="pins-detail-actions"><button className="pin-detail-primary" onClick={onEdit}>Edit</button><button className="pin-detail-primary" onClick={onCamera}>Camera</button><button className="pin-detail-primary" onClick={() => setFollowUp(true)}>Follow-up</button>{attached[0] && <button className="pin-detail-primary" onClick={download}>Save</button>}</div><div className="pins-detail-delete"><button onClick={() => setConfirming('pin')}>Delete PIN</button>{onDeleteNote && <button onClick={() => setConfirming('note')}>Delete Note</button>}</div>{followUp && <SurfaceDialog className="surface-dialog--follow-up" labelledBy="follow-up-title"><h3 id="follow-up-title">Follow-up Reminder</h3>{!isPro ? <><p className="pin-followup-upgrade">Unlock Surface Pro</p><div className="surface-dialog-actions"><button className="surface-dialog-cancel" onClick={() => setFollowUp(false)}>Close</button></div></> : <><p className="pin-followup-name">{pin.name || 'PIN'}</p><label>Days from now<input value={days} onChange={(event) => setDays(event.target.value.replace(/\D/g, '').slice(0, 3))} /></label><label>Reason<textarea value={reason} onChange={(event) => setReason(event.target.value)} /></label><div className="surface-dialog-actions"><button className="surface-dialog-cancel" onClick={() => setFollowUp(false)}>Cancel</button><button className="surface-dialog-confirm" onClick={() => { void onFollowUp(Date.now() + Math.max(0, Number(days) || 1) * 86400000, reason); setFollowUp(false); }}>Save</button></div></>}</SurfaceDialog>}{confirming && <SurfaceDialog className="surface-dialog--pin-confirm" labelledBy="pin-detail-delete-title"><strong id="pin-detail-delete-title">{confirming === 'pin' ? 'Delete this PIN? NoteBlock and captures will remain.' : 'This note is connected to a PIN. Deleting it will also delete the PIN. Linked captures will remain in Captures.'}</strong><div className="surface-dialog-actions"><button className="surface-dialog-cancel" onClick={() => setConfirming(null)}>Cancel</button><button className="surface-dialog-confirm" onClick={() => void (confirming === 'pin' ? onDeletePin() : onDeleteNote?.())}>Confirm</button></div></SurfaceDialog>}</section>; }
function NoteDetail({ note, onBack, onEdit, onDelete }: { note: Note; onBack: () => void; onEdit: () => void; onDelete: () => Promise<void> }) { const [confirming, setConfirming] = useState(false); return <section className="pin-detail"><div className="section-heading"><button className="text-button" onClick={onBack}>‹ Notes</button><button className="text-button" onClick={onEdit}>Edit</button></div><h2>{note.name || 'Note'}</h2><p className="meta">{note.phone || 'No phone'} • {note.dateKey}</p><div className="detail-copy">{note.body || 'No details yet.'}</div><button className="surface-action destructive" onClick={() => setConfirming(true)}>Delete Note</button>{confirming && <SurfaceDialog labelledBy="note-detail-delete-title"><strong id="note-detail-delete-title">Delete this note? Any PIN using it will also be deleted. Captures stay saved.</strong><div className="surface-dialog-actions"><button className="surface-dialog-cancel" onClick={() => setConfirming(false)}>Cancel</button><button className="surface-dialog-destructive" onClick={() => void onDelete()}>Delete</button></div></SurfaceDialog>}</section>; }
function Search({ pins, notes, onPin, onNote, isPro }: { pins: Pin[]; notes: Note[]; onPin: (id: string) => void; onNote: (id: string) => void; isPro: boolean }) { const [query, setQuery] = useState(''); const q = query.trim().toLowerCase(); const results = q ? [...pins.filter((p) => [p.name, p.phone, p.about, p.locationLabel].some((v) => v?.toLowerCase().includes(q))).map((p) => ({ id: p.id, title: p.name || 'PIN', sub: p.phone, kind: 'PIN', open: () => onPin(p.id) })), ...notes.filter((n) => [n.name, n.phone, n.body].some((v) => v?.toLowerCase().includes(q))).map((n) => ({ id: n.id, title: n.name || 'Note', sub: n.phone || n.body, kind: 'Note', open: () => onNote(n.id) }))] : []; return <section className="search-view"><h2>Search</h2>{!isPro ? <p className="surface-action">Unlock Surface Pro</p> : <><input placeholder="Search Surface" value={query} onChange={(event) => setQuery(event.target.value)} />{results.map((item) => <button className="pin-row" key={`${item.kind}-${item.id}`} onClick={item.open}><strong>{item.title}</strong><span>{item.kind} {item.sub}</span></button>)}</>}</section>; }
function PaymentReturn({ onBack, onRefresh }: { onBack: () => void; onRefresh: () => Promise<void> }) {
  const [status, setStatus] = useState('Checking payment...');
  const [error, setError] = useState(false);
  useEffect(() => {
    let active = true;
    const verify = async () => {
      const orderId = sessionStorage.getItem('surface-pending-order');
      if (!orderId) { setStatus('No pending payment was found.'); return; }
      try {
        const token = await getSurfaceFirebase().auth.currentUser?.getIdToken(true);
        if (!token) throw new Error('Sign in required');
        const response = await fetch(`${import.meta.env.VITE_SURFACE_API_BASE_URL ?? 'https://surface-payments.onrender.com'}/payments/verify`, { method: 'POST', headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' }, body: JSON.stringify({ orderId }) });
        const result = await response.json() as { granted?: boolean };
        if (!response.ok) throw new Error('Verification failed');
        sessionStorage.removeItem('surface-pending-order');
        await onRefresh();
        if (active) setStatus(result.granted ? 'Payment verified. Your subscription is active.' : 'Payment is still being verified. Check Surface Pro again shortly.');
      } catch { if (active) { setError(true); setStatus('Payment status could not be checked yet.'); } }
    };
    void verify();
    return () => { active = false; };
  }, [onRefresh]);
  return <section className="payment-return-screen"><h2>{status}</h2><p>Surface only activates paid access after server verification.</p><div className="detail-actions"><button className="surface-action" onClick={onBack}>Surface Pro</button>{error && <button className="surface-action" onClick={() => window.location.reload()}>Try again</button>}</div></section>;
}

function SurfacePro({ user, entitlement, onAccount, onClose, onRefresh }: { user: User; entitlement: SurfaceEntitlement | null; onAccount: () => void; onClose: () => void; onRefresh: () => Promise<void> }) {
  const [proPeriods, setProPeriods] = useState(1);
  const [maxPeriods, setMaxPeriods] = useState(1);
  const [phone, setPhone] = useState<string | null>(null);
  const [loadingPlan, setLoadingPlan] = useState<string | null>(null);
  const [startedAt, setStartedAt] = useState<number | null>(null);
  const [countdown, setCountdown] = useState(90);
  const [message, setMessage] = useState<string | null>(null);
  const [checking, setChecking] = useState(false);
  const currentTier = entitlement?.tier ?? 'FREE';

  useEffect(() => { void getDoc(doc(getSurfaceFirebase().firestore, 'users', user.uid)).then((snapshot) => { const value = snapshot.data()?.phoneNumber; setPhone(typeof value === 'string' ? normalizeIndianMobile(value) : null); }); }, [user.uid]);
  useEffect(() => {
    const check = async () => {
      const orderId = sessionStorage.getItem('surface-pending-order');
      if (!orderId || checking) return;
      setChecking(true);
      try {
        const token = await getSurfaceFirebase().auth.currentUser?.getIdToken(true);
        if (!token) return;
        const response = await fetch(`${import.meta.env.VITE_SURFACE_API_BASE_URL ?? 'https://surface-payments.onrender.com'}/payments/verify`, { method: 'POST', headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' }, body: JSON.stringify({ orderId }) });
        const result = await response.json() as { granted?: boolean };
        sessionStorage.removeItem('surface-pending-order');
        setMessage(result.granted ? 'Payment verified. Subscription is active.' : 'Payment is still being verified.');
        await onRefresh();
      } catch { setMessage('Payment status will update when verification is available.'); }
      finally { setChecking(false); }
    };
    void check();
    window.addEventListener('focus', check);
    return () => window.removeEventListener('focus', check);
  }, [checking, onRefresh]);
  useEffect(() => {
    if (!loadingPlan || !startedAt) return;
    const update = () => {
      const remaining = Math.max(0, Math.ceil((startedAt + 90_000 - Date.now()) / 1000));
      setCountdown(remaining);
      if (remaining === 0) { setLoadingPlan(null); setStartedAt(null); setMessage('Payment is taking longer than expected. Try again.'); }
    };
    update();
    const interval = window.setInterval(update, 500);
    return () => window.clearInterval(interval);
  }, [loadingPlan, startedAt]);
  const checkout = async (tier: PaymentTier, periods: number) => {
    if (loadingPlan) return;
    if (!phone) { setMessage('Add your phone number to continue.'); onAccount(); return; }
    const plan = `surface_${tier.toLowerCase()}_${periods}period`;
    setLoadingPlan(plan); setStartedAt(Date.now()); setCountdown(90); setMessage(null);
    try {
      const token = await getSurfaceFirebase().auth.currentUser?.getIdToken(true);
      if (!token) throw new Error();
      const response = await fetch(`${import.meta.env.VITE_SURFACE_API_BASE_URL ?? 'https://surface-payments.onrender.com'}/payments/create-order`, { method: 'POST', headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' }, body: JSON.stringify({ client: 'pwa', tier, periods, customerPhone: phone }) });
      const result = await response.json() as { order_id?: string; checkout_url?: string; error?: string };
      if (!response.ok || !result.order_id || !result.checkout_url) throw new Error(result.error ?? 'Payment could not start.');
      sessionStorage.setItem('surface-pending-order', result.order_id);
      window.location.assign(result.checkout_url);
    } catch { setLoadingPlan(null); setStartedAt(null); setMessage('Payment could not start. Please try again.'); }
  };
  const cardMessage = loadingPlan ? null : message;
  return <section className="native-subscription">
    <div className="subscription-heading"><h2>Subscription</h2><button className="subscription-close" onClick={onClose} aria-label="Close"><SubscriptionCloseIcon /></button></div>
    <div className="subscription-hero"><span>Upgrade for more of</span><strong>Surface Pro</strong></div>
    <p className="subscription-saving">Save 13% on 3 Months</p>
    <SubscriptionFreeCard current={currentTier === 'FREE'} />
    <SubscriptionPlanCard title="Pro" label={currentTier === 'PRO' ? 'Current plan' : 'Standard'} price="₹99 / 30 days" tier="PRO" periods={proPeriods} current={currentTier === 'PRO'} loading={loadingPlan?.startsWith('surface_pro_') ?? false} countdown={countdown} message={cardMessage} onChange={setProPeriods} onCheckout={checkout} features={['Basic Cloud', 'Everything in Free', 'Truly Unlimited', 'Advanced Capture', 'Search Anything', 'Follow-up reminder', 'Enhanced Support']} />
    <SubscriptionPlanCard title="Max" label={currentTier === 'MAX' ? 'Current plan' : 'Diamond'} price="₹149 / 30 days" tier="MAX" periods={maxPeriods} current={currentTier === 'MAX'} loading={loadingPlan?.startsWith('surface_max_') ?? false} countdown={countdown} message={cardMessage} onChange={setMaxPeriods} onCheckout={checkout} features={['Everything in Pro', 'True Cloud', 'WhatsApp integration', 'Phone integration', 'Telegram integration', 'Diamond Support']} />
    <div className="subscription-help"><strong>Confused?<br />Know which<br />plan best suits<br />for you›</strong><a href="mailto:girisatya584@gmail.com">Ask Surface</a></div>
  </section>;
}

function SubscriptionFreeCard({ current }: { current: boolean }) { return <section className="subscription-card subscription-card--free"><div className="subscription-card-title"><h3>Free</h3>{current && <span>Current plan</span>}</div><div className="subscription-features">{['Core Surface experience', 'PIN Creation', 'Captures', 'Notes', 'Gallery', 'Camera'].map((feature) => <SubscriptionFeature key={feature}>{feature}</SubscriptionFeature>)}</div></section>; }
function SubscriptionPlanCard({ title, label, price, tier, periods, current, loading, countdown, message, onChange, onCheckout, features }: { title: string; label: string; price: string; tier: PaymentTier; periods: number; current: boolean; loading: boolean; countdown: number; message: string | null; onChange: (value: number) => void; onCheckout: (tier: PaymentTier, periods: number) => void; features: string[] }) { const total = paymentAmount(tier, periods); const isDiamond = title === 'Max'; return <section className="subscription-card subscription-card--paid"><div className="subscription-card-title"><h3>{title}</h3><span className={current ? 'subscription-current' : isDiamond ? 'subscription-diamond' : ''}>{label}</span></div><p className="subscription-price">{price}</p><SubscriptionQuantity value={periods} onChange={onChange} /><p className="subscription-total">Total: ₹{total} / {periods * 30} days</p><p className={`subscription-duration ${periods === 3 ? 'subscription-duration--saving' : ''}`}>{periods * 30} days{periods === 3 ? '  •  Save 13%' : ''}</p>{!current && <button className="subscription-checkout" disabled={loading} onClick={() => void onCheckout(tier, periods)}>{loading ? <span className="subscription-spinner" aria-label="Starting secure payment" /> : `Upgrade to ${title}`}</button>}{loading && <div className="subscription-wait"><span>Starting secure payment...</span><strong>{String(Math.floor(countdown / 60)).padStart(2, '0')}:{String(countdown % 60).padStart(2, '0')}</strong><span>This can take up to 90 seconds.</span></div>}{!loading && message && <p className="subscription-message">{message}</p>}<div className="subscription-features">{features.map((feature) => <SubscriptionFeature key={feature} diamond={feature === 'Diamond Support'}>{feature}</SubscriptionFeature>)}</div></section>; }
function SubscriptionQuantity({ value, onChange }: { value: number; onChange: (value: number) => void }) { return <div className="subscription-quantity"><button aria-label="Decrease periods" disabled={value <= 1} onClick={() => onChange(Math.max(1, value - 1))}>−</button><strong>{value} {value === 1 ? 'period' : 'periods'}</strong><button aria-label="Increase periods" disabled={value >= 12} onClick={() => onChange(Math.min(12, value + 1))}>+</button></div>; }
function SubscriptionFeature({ children, diamond = false }: { children: string; diamond?: boolean }) { return <div className={diamond ? 'subscription-feature subscription-feature--diamond' : 'subscription-feature'}>{diamond ? <SubscriptionDiamondIcon /> : <SubscriptionCheckIcon />}<span>{children}</span></div>; }
function SubscriptionCloseIcon() { return <svg viewBox="0 0 960 960" aria-hidden="true"><path d="m256 200-56 56 224 224-224 224 56 56 224-224 224 224 56-56-224-224 224-224-56-56-224 224-224-224Z" /></svg>; }
function SubscriptionCheckIcon() { return <svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 16.17-4.17-4.17L3.41 13.41 9 19 21 7l-1.41-1.41L9 16.17Z" /></svg>; }
function SubscriptionDiamondIcon() { return <svg viewBox="0 0 960 960" aria-hidden="true"><path d="M480 80 120 436l200 244h320l200-244L480 80ZM183 680l-85 85 57 56 85-85-57-56Zm257 80v120h80V760h-80Zm335-80-57 57 85 85 57-57-85-85ZM480 192l210 208H270l210-208ZM358 600l-99-120h442l-99 120H358Z" /></svg>; }
function Account({ user, onBack, onSignedOut, setMessage }: { user: User; onBack: () => void; onSignedOut: () => void | Promise<void>; setMessage: (value: string) => void }) {
  const { firestore } = getSurfaceFirebase();
  const [data, setData] = useState({ name: '', phone: '' });
  const [current, setCurrent] = useState(''); const [next, setNext] = useState(''); const [confirm, setConfirm] = useState(''); const [deletePassword, setDeletePassword] = useState('');
  const [mode, setMode] = useState<'none' | 'password' | 'delete'>('none'); const [message, setLocalMessage] = useState<string | null>(null);
  useEffect(() => { void getDoc(doc(firestore, 'users', user.uid)).then((snapshot) => { const value = snapshot.data() ?? {}; setData({ name: typeof value.displayName === 'string' ? value.displayName : user.displayName ?? '', phone: typeof value.phoneNumber === 'string' ? value.phoneNumber : '' }); }).catch(() => setData((currentData) => ({ ...currentData, name: user.displayName ?? '' }))); }, [firestore, user.displayName, user.uid]);
  const report = (value: string) => { setLocalMessage(value); setMessage(value); };
  const save = async () => { try { await updateDoc(doc(firestore, 'users', user.uid), { displayName: data.name.trim() || null, phoneNumber: data.phone.trim() || null }); report('Account information saved.'); } catch { report('Account information could not be saved.'); } };
  const change = async () => { if (next !== confirm) return report('Passwords do not match.'); try { await reauthenticateWithCredential(user, EmailAuthProvider.credential(user.email ?? '', current)); await updatePassword(user, next); report('Password changed.'); setMode('none'); } catch { report('Password change failed. Check your current password.'); } };
  const reset = async () => { try { if (!user.email) throw new Error(); await sendPasswordResetEmail(getSurfaceFirebase().auth, user.email); report('Password reset email sent.'); } catch { report('Password reset could not be sent.'); } };
  const remove = async () => { try { await reauthenticateWithCredential(user, EmailAuthProvider.credential(user.email ?? '', deletePassword)); const token = await user.getIdToken(true); const response = await fetch(`${import.meta.env.VITE_SURFACE_API_BASE_URL ?? 'https://surface-payments.onrender.com'}/account/delete`, { method: 'POST', headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' }, body: '{}' }); if (!response.ok) throw new Error(); await signOut(getSurfaceFirebase().auth); } catch { report('Account deletion could not be completed.'); } };
  return <section className="native-account-screen">
    <div className="native-account-title"><h2>Account</h2><button onClick={onBack}>Back</button></div>
    <h3>ACCOUNT INFORMATION</h3>
    <NativeAccountField label="Name" value={data.name} onChange={(name) => setData((value) => ({ ...value, name }))} />
    <NativeAccountField label="Username" value={data.name} onChange={(name) => setData((value) => ({ ...value, name }))} />
    <NativeAccountField label="Email" value={user.email ?? ''} readOnly onChange={() => undefined} />
    <NativeAccountField label="Phone number" value={data.phone} onChange={(phone) => setData((value) => ({ ...value, phone }))} />
    <button className="native-account-save" onClick={() => void save()}>Save changes</button>
    <h3>ACCOUNT SECURITY</h3>
    <div className="native-account-security"><NativeAccountRow title="Change password" onClick={() => setMode('password')} /><NativeAccountRow title="Send password reset email" onClick={() => void reset()} /><NativeAccountRow title="Delete account" onClick={() => setMode('delete')} /><NativeAccountRow title="Sign out" onClick={() => void onSignedOut()} /></div>
    {message && <p className="native-account-message">{message}</p>}
    {mode === 'password' && <SurfaceDialog className="surface-dialog--material" labelledBy="password-dialog-title" onDismiss={() => setMode('none')} dismissOnBackdrop><h4 id="password-dialog-title">Change password</h4><NativeAccountField label="Current password" value={current} password onChange={setCurrent} /><NativeAccountField label="New password" value={next} password onChange={setNext} /><NativeAccountField label="Confirm new password" value={confirm} password onChange={setConfirm} /><div className="surface-dialog-actions"><button className="surface-dialog-cancel" onClick={() => setMode('none')}>Cancel</button><button className="surface-dialog-action" onClick={() => void change()}>Save</button></div></SurfaceDialog>}
    {mode === 'delete' && <SurfaceDialog className="surface-dialog--material" labelledBy="delete-account-dialog-title" onDismiss={() => setMode('none')} dismissOnBackdrop><h4 id="delete-account-dialog-title">Delete account?</h4><p>Your cloud account will be deleted after re-authentication. Local Surface data on this device will be kept.</p><NativeAccountField label="Current password" value={deletePassword} password onChange={setDeletePassword} /><div className="surface-dialog-actions"><button className="surface-dialog-cancel" onClick={() => setMode('none')}>Cancel</button><button className="surface-dialog-destructive" onClick={() => void remove()}>Delete</button></div></SurfaceDialog>}
  </section>;
}

function NativeAccountField({ label, value, password = false, readOnly = false, onChange }: { label: string; value: string; password?: boolean; readOnly?: boolean; onChange: (value: string) => void }) {
  const [visible, setVisible] = useState(false);
  return <label className="native-account-field"><span>{label}</span><div><input aria-label={label} type={password && !visible ? 'password' : 'text'} readOnly={readOnly} value={value} onChange={(event) => onChange(event.target.value)} />{password && <button type="button" aria-label={visible ? 'Hide password' : 'Show password'} onClick={() => setVisible((value) => !value)}><NativeEyeIcon hidden={visible} /></button>}</div></label>;
}

function NativeAccountRow({ title, onClick }: { title: string; onClick: () => void }) { return <button className="native-account-row" onClick={onClick}><span>{title}</span><NativeAccountChevron /></button>; }
function NativeAccountChevron() { return <svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 18 6-6-6-6" /></svg>; }
function NativeEyeIcon({ hidden }: { hidden: boolean }) { return <svg viewBox="0 0 24 24" aria-hidden="true"><path d={hidden ? 'M2.27 1.72 22.27 21.72l-1.42 1.42-3.03-3.03A11.7 11.7 0 0 1 12 21C7 21 2.73 17.89 1 13.5a12.8 12.8 0 0 1 4.1-5.08L.85 3.14l1.42-1.42ZM12 18.5c1.55 0 3-.4 4.26-1.1l-1.53-1.53A4.97 4.97 0 0 1 7 12c0-.27.02-.53.06-.78l-1.8-1.8A10.8 10.8 0 0 0 3.2 13.5c1.82 3.02 5.05 5 8.8 5ZM12 5.5c-1.55 0-3 .4-4.26 1.1l1.52 1.52A4.97 4.97 0 0 1 17 12c0 .08-.01.16-.01.24l1.8 1.8a10.8 10.8 0 0 0 2.06-4.08C18.98 7.48 15.75 5.5 12 5.5Z' : 'M12 4.5C7 4.5 2.73 7.61 1 12c1.73 4.39 6 7.5 11 7.5s9.27-3.11 11-7.5c-1.73-4.39-6-7.5-11-7.5Zm0 13a5 5 0 1 1 0-10 5 5 0 0 1 0 10Zm0-2a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z'} /></svg>; }
function Camera({ onSaved, onMessage }: { onSaved: (item: SurfaceMedia) => void; onMessage: (value: string) => void }) { const [location, setLocation] = useState<SurfaceLocation | null>(readSurfaceLocation()); const input = React.useRef<HTMLInputElement>(null); useEffect(() => { if (!navigator.geolocation) return; navigator.geolocation.getCurrentPosition((position) => { const next = { latitude: position.coords.latitude, longitude: position.coords.longitude, timestamp: Date.now() }; localStorage.setItem('surface-location', JSON.stringify(next)); setLocation(next); }, () => undefined, { enableHighAccuracy: true, maximumAge: 120000, timeout: 3000 }); }, []); const label = formatSurfaceLocation(location); return <section className="camera-view"><h2>Camera</h2>{label && <p className="meta">{label}</p>}<input ref={input} className="camera-input" type="file" accept="image/*" capture="environment" onChange={async (event) => { const file = event.target.files?.[0]; if (!file) return; try { onSaved(await saveMedia(file, location, true)); } catch { onMessage('Photo could not be saved.'); } event.target.value = ''; }} /><button className="primary-action camera-button" onClick={() => input.current?.click()}>Capture</button></section>; }
function MediaGrid({ title, items, pins, onImport, onDelete, onCreatePin, onConnectExisting }: { title: string; items: SurfaceMedia[]; pins: Pin[]; onImport?: (file: File) => Promise<void>; onDelete: (id: string) => Promise<void>; onCreatePin?: (id: string) => void; onConnectExisting?: (mediaId: string, pinId: string) => Promise<void> }) { const [viewer, setViewer] = useState<number | null>(null); const [pendingDelete, setPendingDelete] = useState<string | null>(null); const [connectFor, setConnectFor] = useState<string | null>(null); const picker = React.useRef<HTMLInputElement>(null); if (viewer !== null && items[viewer]) return <MediaViewer items={items} index={viewer} onClose={() => setViewer(null)} onChange={setViewer} />; return <section className="media-view"><div className="section-heading"><h2>{title}</h2>{onImport && <><input ref={picker} className="visually-hidden" type="file" accept="image/*" onChange={async (e) => { const file = e.target.files?.[0]; if (file) await onImport(file); e.target.value = ''; }} /><button className="icon-button" onClick={() => picker.current?.click()}>＋</button></>}</div>{items.length === 0 ? <div className="empty-state"><img src="/surface-logo.svg" alt="" /><strong>Oops!!<br />Surface {title.replace('Surface ', '')} is empty!</strong>{onImport && <button className="surface-action" onClick={() => picker.current?.click()}>＋ Upload images</button>}{onCreatePin && <button className="surface-action" onClick={() => window.location.hash = '#pins/new'}>＋ Create PIN</button>}</div> : <div className="media-grid">{items.map((item, index) => <article className="media-card" key={item.id}><button className="media-open" onClick={() => setViewer(index)}><img src={objectUrl(item.processed)} alt="" /><small>{item.dateKey} {item.locationLabel && `• ${item.locationLabel}`}</small></button>{(onCreatePin || onConnectExisting) && <div className="media-actions">{onCreatePin && <button className="surface-action" onClick={() => onCreatePin(item.id)}>Create PIN</button>}{onConnectExisting && <button className="surface-action" onClick={() => setConnectFor(item.id)}>Connect Existing</button>}</div>}<button className="media-delete" aria-label="Delete media" onClick={() => setPendingDelete(item.id)}>Delete</button></article>)}</div>}{pendingDelete && <div className="overlay"><div className="dialog"><h3>Delete this image?</h3><p>This cannot be undone.</p><div className="form-actions"><button className="surface-action" onClick={() => setPendingDelete(null)}>Cancel</button><button className="surface-action destructive" onClick={async () => { const id = pendingDelete; setPendingDelete(null); await onDelete(id); }}>Delete</button></div></div></div>}{connectFor && <div className="overlay"><div className="dialog"><h3>Connect to a PIN</h3><select defaultValue="" onChange={async (event) => { if (event.target.value && onConnectExisting) { const mediaId = connectFor; setConnectFor(null); await onConnectExisting(mediaId, event.target.value); } }}><option value="">Choose a PIN</option>{pins.map((pin) => <option key={pin.id} value={pin.id}>{pin.name || 'Unnamed PIN'}</option>)}</select><button className="surface-action" onClick={() => setConnectFor(null)}>Cancel</button></div></div>}</section>; }
function MediaViewer({ items, index, onClose, onChange }: { items: SurfaceMedia[]; index: number; onClose: () => void; onChange: (index: number) => void }) { const [scale, setScale] = useState(1); const [offset, setOffset] = useState({ x: 0, y: 0 }); const start = React.useRef<{ x: number; y: number; time: number } | null>(null); const reset = () => { setScale(1); setOffset({ x: 0, y: 0 }); }; const download = () => { const link = document.createElement('a'); link.href = objectUrl(items[index].processed); link.download = `Surface-${items[index].dateKey.replaceAll('/', '-')}.jpg`; link.click(); }; return <div className="media-viewer" onPointerDown={(event) => { start.current = { x: event.clientX, y: event.clientY, time: Date.now() }; }} onPointerUp={(event) => { const current = start.current; if (!current) return; const dx = event.clientX - current.x; const dy = event.clientY - current.y; if (scale === 1 && Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy) && Date.now() - current.time < 700) { if (dx < 0 && index < items.length - 1) onChange(index + 1); if (dx > 0 && index > 0) onChange(index - 1); } else if (scale > 1 && (Math.abs(dx) > 4 || Math.abs(dy) > 4)) setOffset((value) => ({ x: value.x + dx, y: value.y + dy })); start.current = null; }}><button className="viewer-close" onClick={onClose}>×</button><img src={objectUrl(items[index].processed)} alt="" style={{ transform: `translate(${offset.x}px, ${offset.y}px) scale(${scale})` }} onDoubleClick={() => { if (scale === 1) setScale(2); else reset(); }} /><div className="viewer-controls"><button disabled={index === 0} onClick={() => onChange(index - 1)}>‹</button><button onClick={() => setScale((value) => Math.min(4, value + .5))}>＋</button><button onClick={() => setScale((value) => Math.max(1, value - .5))}>−</button><button onClick={download} aria-label="Save image">↓</button><button disabled={index === items.length - 1} onClick={() => onChange(index + 1)}>›</button></div></div>; }
function GroundNav({ route, routeTo, isPro }: { route: Route; routeTo: (route: Route) => void; isPro: boolean }) { return <nav className="ground-nav"><button className="nav-item" onClick={() => routeTo('camera')} aria-label="Camera"><img src="/icons/camera.svg" alt="" /></button><button className="nav-item" onClick={() => routeTo(isPro ? 'search' : 'notes')} aria-label={isPro ? 'Search' : 'Notes'}><img src={isPro ? '/icons/search.svg' : '/icons/notes.svg'} alt="" /></button><button className="nav-item" onClick={() => routeTo('captures')} aria-label="Captures"><img src="/icons/gallery.svg" alt="" /></button></nav>; }
if ('serviceWorker' in navigator) window.addEventListener('load', () => void navigator.serviceWorker.register('/sw.js'));
createRoot(document.getElementById('root')!).render(<React.StrictMode><App /></React.StrictMode>);
